<style>
:root{--yellow:#fff500;--black:#050505;--light:#f0eeee;--gray:#d6d6d6;--ink:#202020}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:Arial,Helvetica,sans-serif;color:var(--ink);background:#fff}
button,input{font:inherit}
button{cursor:pointer}
.btn{border:0}
.site-header{height:80px;background:#000;color:#fff;display:flex;align-items:center;padding:0 18px;position:relative;z-index:5}
.brand{font-size:37px;letter-spacing:-2.1px;font-weight:700;color:#fff;text-decoration:none;white-space:nowrap}
.brand .notes{color:var(--yellow)}
.brand sup{font-size:8px;letter-spacing:0;vertical-align:top;margin-left:4px}
.header-actions{margin-left:auto;display:flex;gap:17px;align-items:center}
.icon-btn{background:none;color:var(--yellow);padding:4px;width:34px;height:38px;position:relative}
