.searchbox{height:42px;border-radius:25px;background:#f4f2f2;display:flex;align-items:center;padding:0 13px;margin:0 auto;width:100%;max-width:350px;color:#323232}
.searchbox .search-icon{border-color:#111;position:relative;top:auto;left:auto;flex:none;width:17px;height:17px}
.searchbox .search-icon:after{background:#111;width:10px;left:13px;top:14px}
