.listing{padding:29px 18px 45px}
.book-row{min-height:80px;background:var(--light);display:flex;margin:0 0 15px;text-decoration:none;color:#222;position:relative}
.book-icon{width:68px;min-width:68px;background:#d7d7d7;display:flex;align-items:center;justify-content:center;font-size:25px}
.book-info{padding:12px 35px 11px 12px;display:flex;flex-direction:column;justify-content:space-between;min-height:80px;flex:1}
.book-title{font-size:21px;line-height:1.35;text-transform:uppercase;font-weight:500}
.book-author{font-size:15px}
.chevron{position:absolute;right:13px;top:50%;transform:translateY(-50%);font-size:36px;font-weight:200}
.author-row{background:#000;color:#fff;padding:20px 16px;margin-bottom:15px;font-size:19px}
.author-row span{color:var(--yellow)}
.drawer-shade{position:fixed;inset:0;background:rgba(0,0,0,.35);z-index:8;display:none}
.drawer{position:fixed;z-index:9;top:0;bottom:0;left:0;width:min(290px,78vw);background:#000;color:#fff;border-right:6px solid var(--yellow);transform:translateX(-105%);transition:transform .25s ease;overflow-y:auto}
.drawer.open{transform:translateX(0)}
.drawer-shade.open{display:block}
.drawer-brand{height:81px;padding:18px 15px;border-bottom:1px solid #555}
.drawer-brand .brand{font-size:34px}
.menu-link{height:73px;border-bottom:1px solid #777;display:flex;align-items:center;justify-content:space-between;padding:0 18px;color:#fff;text-decoration:none;font-size:17px}
.menu-link .arrow{font-size:32px}
.signup{margin:24px 18px;background:var(--yellow);height:44px;border-radius:5px;width:calc(100% - 36px);font-weight:bold;font-size:16px}
.search-panel{display:none;position:fixed;z-index:7;top:80px;left:0;right:0;background:#fff;padding:15px;box-shadow:0 3px 8px #777}
.search-panel.open{display:block}
.search-panel .searchbox{border:1px solid #ddd}
.study-list{padding:30px 18px}
.study-item{height:auto;min-height:62px;background:var(--light);margin-bottom:16px;padding:17px 44px 17px 20px;position:relative;font-size:18px}
.study-item .chevron{font-size:32px}
.article{padding:26px 19px 40px;font-size:17px;line-height:1.65}
.article h2{font-size:23px;line-height:1.25;margin:0 0 30px}
.article h3{font-size:20px;margin:25px 0 18px}
.article p{margin:0 0 19px}
.article ul{padding-left:21px;margin:18px 0}
.article li{padding-left:1px;margin:0 0 18px}
.article-select{background:#000;color:var(--yellow);padding:17px 20px;font-size:18px;margin:0 0 26px;display:flex;justify-content:space-between}
.pager{display:flex;justify-content:space-between;gap:20px;margin:30px 0}
.pager .btn{flex:1;height:48px;background:#ddd;color:#222;font-size:15px}
.pager .btn.next{background:#000;color:var(--yellow)}
.site-footer{background:#050505;color:#fff;text-align:center;padding:24px 20px 0}
.site-footer .brand{font-size:42px}
.site-footer p{font-size:14px;line-height:1.5}
.footer-links{background:#3c3c3c;margin:25px -20px 0;padding:20px 14px;font-size:14px;line-height:2}
.legal{background:#ccc;color:#222;margin:0 -20px;padding:18px 12px 28px;font-size:13px;line-height:2}
.top-button{position:fixed;right:12px;bottom:14px;background:#000;color:#fff;padding:6px 9px;z-index:4}
.hidden{display:none!important}
@media(max-width:360px){
 .brand{font-size:31px}.header-actions{gap:9px}.home-hero h1{font-size:26px}
 .book-title{font-size:18px}.alphabet .btn{min-width:22px;padding:0 3px}
}
</style>
