<script>
const books=[
 {title:"Absalom, Absalom!",author:"William Faulkner"},
 {title:"The Absolutely True Diary of a Part-Time Indian",author:"Sherman Alexie"},
 {title:"Adam Bede",author:"George Eliot"},
 {title:"The Adventures of Huckleberry Finn",author:"Mark Twain"},
 {title:"The Adventures of Tom Sawyer",author:"Mark Twain"},
 {title:"The Age of Innocence",author:"Edith Wharton"},
 {title:"Alice's Adventures in Wonderland",author:"Lewis Carroll"},
 {title:"All Quiet on the Western Front",author:"Erich Maria Remarque"},
 {title:"Daisy Miller",author:"Henry James"},
 {title:"David Copperfield",author:"Charles Dickens"},
 {title:"The Day of the Locust",author:"Nathanael West"},
 {title:"Death and the King's Horseman",author:"Wole Soyinka"},
 {title:"Fahrenheit 451",author:"Ray Bradbury"},
 {title:"A Farewell to Arms",author:"Ernest Hemingway"},
 {title:"Farewell to Manzanar",author:"Jeanne W. Houston and James D. Houston"},
 {title:"Far from the Madding Crowd",author:"Thomas Hardy"},
 {title:"Chinua Achebe",author:""},
 {title:"Things Fall Apart",author:"Chinua Achebe"},
 {title:"Henry Adams",author:""},
 {title:"The Education of Henry Adams",author:"Henry Adams"}
];
const letters="ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("");
let activeLetter="A",sortMode="title";
const alphabet=document.getElementById("alphabet"),listing=document.getElementById("literatureList");
function renderAlphabet(){alphabet.innerHTML="";["All",...letters].forEach(ch=>{let b=document.createElement("button");b.className="btn"+((ch==="All"&&activeLetter==="All"||ch===activeLetter)?" selected":"");b.textContent=ch;b.onclick=()=>{activeLetter=ch;renderAlphabet();renderBooks()};alphabet.appendChild(b)})}
function renderBooks(){
 let data=books.filter(b=>activeLetter==="All"||b.title.toUpperCase().startsWith(activeLetter));
 if(sortMode==="author") data.sort((a,b)=>a.author.localeCompare(b.author)||a.title.localeCompare(b.title));
 else data.sort((a,b)=>a.title.localeCompare(b.title));
 listing.innerHTML="";
 if(sortMode==="author"){
  data.forEach(b=>{
   if(!b.author){let a=document.createElement("div");a.className="author-row";a.innerHTML=b.title.replace(" "," <span>")+"</span>";listing.appendChild(a)}
   else listing.appendChild(makeBook(b));
  });
 }else data.forEach(b=>listing.appendChild(makeBook(b)));
}
function makeBook(b){let a=document.createElement("a");a.href="#";a.className="book-row btn";a.innerHTML='<span class="book-icon">▣</span><span class="book-info"><span class="book-title"></span><span class="book-author"></span></span><span class="chevron">›</span>';a.querySelector(".book-title").textContent=b.title;a.querySelector(".book-author").textContent=b.author;a.onclick=e=>{e.preventDefault();if(b.title.includes("Accounting"))showView("article")};return a}
renderAlphabet();renderBooks();
document.getElementById("sortTitle").onclick=()=>{sortMode="title";document.getElementById("sortTitle").classList.add("active");document.getElementById("sortAuthor").classList.remove("active");renderBooks()};
document.getElementById("sortAuthor").onclick=()=>{sortMode="author";document.getElementById("sortAuthor").classList.add("active");document.getElementById("sortTitle").classList.remove("active");renderBooks()};
const guides=["Accounting Principles I","Accounting Principles II","Algebra I","Algebra II","American Government","Anatomy and Physiology","Astronomy","Basic Math & Pre-Algebra","Biochemistry I","Biology","Business Math"];
const studyList=document.getElementById("studyList");
guides.forEach(g=>{let d=document.createElement("div");d.className="study-item btn";d.textContent=g;d.innerHTML='<span>'+g+'</span><span class="chevron">›</span>';d.onclick=()=>showView("article");studyList.appendChild(d)});
function showView(name){
 document.querySelectorAll("main").forEach(m=>m.classList.add("hidden"));
 (document.getElementById(name+"View")||document.getElementById("homeView")).classList.remove("hidden");
 closeMenu();window.scrollTo(0,0);
}
document.querySelectorAll("[data-view]").forEach(el=>el.addEventListener("click",e=>{e.preventDefault();showView(el.dataset.view)}));
const drawer=document.getElementById("drawer"),shade=document.getElementById("shade");
function closeMenu(){drawer.classList.remove("open");shade.classList.remove("open")}
document.getElementById("menuToggle").onclick=()=>{drawer.classList.add("open");shade.classList.add("open")};
shade.onclick=closeMenu;
document.getElementById("searchToggle").onclick=()=>document.getElementById("searchPanel").classList.toggle("open");
function doSearch(){let v=document.getElementById("searchInput").value.toLowerCase();if(v.includes("account"))showView("study");else showView("literature")}
document.getElementById("searchSubmit").onclick=doSearch;
document.getElementById("searchInput").addEventListener("keydown",e=>{if(e.key==="Enter")doSearch()});
document.querySelectorAll(".home-hero .submit-search").forEach(b=>b.onclick=()=>showView("literature"));
document.getElementById("nextSection").onclick=()=>document.querySelector("#articleView h2:nth-of-type(2)").scrollIntoView({behavior:"smooth"});
const topButton=document.getElementById("topButton");
window.addEventListener("scroll",()=>{topButton.classList.toggle("hidden",window.scrollY<300)});
topButton.onclick=()=>window.scrollTo({top:0,behavior:"smooth"});
</script>
